// Los 4 listados publicos de la web. Con rows=500 cabe el catalogo entero en
// una sola peticion por listado, en vez de recorrer 10 paginas de 15.
const BASE = 'https://www.inmobiliariaceballos.com';
const L = [
  { operacion: 'compra',   provincia: 'Guadalajara', ruta: 'BuyProperties/19',  oper: 'compra',   prov: '19' },
  { operacion: 'compra',   provincia: 'Madrid',      ruta: 'BuyProperties/28',  oper: 'compra',   prov: '28' },
  { operacion: 'alquiler', provincia: 'Guadalajara', ruta: 'RentProperties/19', oper: 'alquiler', prov: '19' },
  { operacion: 'alquiler', provincia: 'Madrid',      ruta: 'RentProperties/28', oper: 'alquiler', prov: '28' },
];
return L.map((x) => ({ json: { ...x, url:
  `${BASE}/es-ES/Content/${x.ruta}?pagina=1&rows=500&orden=&dirorden=desc&ref=` +
  `&operacion=${x.oper}&tipoinm=ALL&provincia=${x.prov}&munic=0&zona=0` +
  `&precio1=&precio2=&habit1=&habit2=&superf1=&superf2=&banos1=&banos2=` }}));

// Extrae los inmuebles del HTML del listado. La web es una app ASP.NET que
// sirve HTML plano, asi que no hace falta navegador.
const BASE = 'https://www.inmobiliariaceballos.com';
// La agencia publica 99.999.999 EUR cuando el precio es "a consultar".
const PRECIO_CENTINELA = 99999999;

const ENT = {'&aacute;':'á','&eacute;':'é','&iacute;':'í','&oacute;':'ó','&uacute;':'ú',
 '&Aacute;':'Á','&Eacute;':'É','&Iacute;':'Í','&Oacute;':'Ó','&Uacute;':'Ú',
 '&ntilde;':'ñ','&Ntilde;':'Ñ','&uuml;':'ü','&nbsp;':' ','&quot;':'"','&apos;':"'",
 '&lt;':'<','&gt;':'>'};
const dec = (s) => String(s ?? '')
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&[a-zA-Z]+;/g, (e) => ENT[e] ?? e)
  .replace(/&amp;/g, '&');                       // siempre el ultimo
const txt = (s) => dec(String(s ?? '').replace(/<[^>]+>/g, '')).replace(/\s+/g, ' ').trim();
const ent = (s) => { const m = String(s ?? '').replace(/\./g, '').match(/\d+/); return m ? Number(m[0]) : null; };

const salida = [];
for (const it of $input.all()) {
  const meta = $('Listados a consultar').itemMatching(it.pairedItem?.item ?? 0)?.json
            ?? $('Listados a consultar').first().json;
  const html = String(it.json.data ?? it.json.body ?? '');

  // El listado publica su propio total. Sirve de suma de control: si el
  // parseo no cuadra, la maquetacion ha cambiado y es mejor fallar a la vista
  // que insertar datos a medias.
  const totalWeb = ent((html.match(/id="sTotInm"[^>]*>(\d+)</) || [])[1]);
  const bloques = html.split(/(?=<div id="\d+" class="row property-row)/).slice(1);

  const encontrados = [];
  for (const b of bloques) {
    const id = ent((b.match(/^<div id="(\d+)"/) || [])[1]);
    if (!id) continue;
    const saca = (re) => { const m = b.match(re); return m ? txt(m[1]) : ''; };
    // El tipo sale del alt de la foto, no del <h2>: en muchas fichas el <h2>
    // es un titular comercial y no el tipo de inmueble.
    const alt = saca(/alt="([^"]*)"/);
    const corte = alt.indexOf('.');
    const precioTexto = saca(/<div class="col-sm-5"><strong class="txt15">([\s\S]*?)<\/strong>/);
    const precioNum = ent(precioTexto);
    encontrados.push({
      Referencia: saca(/PropertyDetail\/\d+"><strong>([^<]+)<\/strong>/) || '',
      Operacion: meta.operacion,
      Provincia: meta.provincia,
      Tipo: (corte === -1 ? alt : alt.slice(0, corte)).trim(),
      Zona: corte === -1 ? '' : alt.slice(corte + 1).trim(),
      Titulo: saca(/<h2>([\s\S]*?)<\/h2>/),
      PrecioTexto: (precioNum !== null && precioNum >= PRECIO_CENTINELA) ? 'A consultar' : precioTexto,
      Superficie: saca(/fa-square"><\/i>\s*([^<]*)</),
      Habitaciones: saca(/fa-bed"><\/i>\s*([^<]*)</),
      Url: `${BASE}/es-ES/Content/PropertyDetail/${id}`,
      IdFicha: String(id),
      Activo: 'si',
      VistoUltima: $now.setZone('Europe/Madrid').toISO(),
    });
  }
  if (totalWeb !== null && encontrados.length !== totalWeb) {
    throw new Error(`Inventario ${meta.operacion}/${meta.provincia}: la web anuncia ${totalWeb} inmuebles y se extrajeron ${encontrados.length}. Probable cambio de maquetacion; no se inserta nada.`);
  }
  for (const e of encontrados) if (e.Referencia) salida.push({ json: e });
}
if (!salida.length) throw new Error('Inventario: no se extrajo ningun inmueble de los 4 listados.');
return salida;
